{
  "templateExample": true,
  "schemas": [
    {
      "$id": "gts://gts.frontx.mfes.comm.action.v1~frontx.demo.action.refresh_profile.v1~",
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "$comment": "Self-contained and closed: re-declares every property action.v1 would otherwise provide and rejects any undeclared field, on itself and on its own payload.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "type": {
          "x-gts-ref": "/$id"
        },
        "target": {
          "x-gts-ref": "gts.frontx.mfes.ext.extension.v1~frontx.screensets.layout.screen.v1~frontx.demo.screens.profile.v1"
        },
        "payload": {
          "type": "object",
          "additionalProperties": false
        },
        "timeout": {
          "type": "number",
          "minimum": 1
        }
      },
      "required": [
        "type",
        "target"
      ]
    }
